import { useState, type HTMLAttributes, type MouseEvent } from "react";
import { Button } from "../ui/Button";
import { InputOTP } from "../ui/InputOTP";
import { Link } from "../ui/Link";
import { CompositionRoot } from "./_CompositionRoot";
import type { CompositionSurfaceProps } from "./composition";

export interface DeviceVerificationCardProps extends Omit<HTMLAttributes<HTMLDivElement>, "title" | "color">, CompositionSurfaceProps {
  "data-balsa"?: string;
  title?: string;
  description?: string;
  length?: number;
  onVerify?: (code: string) => void;
  onResend?: () => void;
}

export function DeviceVerificationCard({
  title = "Confirm this device",
  description = "Enter the six digits sent to ada@example.com.",
  length = 6,
  headingLevel,
  shadow,
  theme,
  onVerify,
  onResend,
  "data-balsa": _dataBalsa,
  ...domProps
}: DeviceVerificationCardProps) {
  void _dataBalsa;
  const [code, setCode] = useState("");
  const complete = code.length === length;

  function handleResend(event: MouseEvent<HTMLAnchorElement>) {
    event.preventDefault();
    onResend?.();
  }

  return (
    <CompositionRoot
      {...domProps}
      title={title}
      description={description}
      headingLevel={headingLevel}
      shadow={shadow}
      theme={theme}
      data-composition="device-verification"
      footer={(
        <Button className="w-full" disabled={!complete} onClick={() => onVerify?.(code)}>
          Verify device
        </Button>
      )}
    >
      <InputOTP
        id="device-code"
        value={code}
        onValueChange={setCode}
        label="Verification code"
        length={length}
        grouped
        fluid
        separatorEvery={3}
      />
      <p className="mt-balsa-lg text-xs text-balsa-muted-foreground">
        The code expires in 10 minutes.{" "}
        <Link href="#" onClick={handleResend}>Send it again</Link>
      </p>
    </CompositionRoot>
  );
}

import { type HTMLAttributes, type ReactNode } from "react";
import { mergeClasses } from "../ui/classes";
import { ApplicationCard } from "./ApplicationCard";
import type { CompositionSurfaceProps } from "./composition";

export interface CompositionRootProps extends Omit<HTMLAttributes<HTMLDivElement>, "title" | "color">, CompositionSurfaceProps {
  "data-balsa"?: string;
  title: string;
  description?: string;
  action?: ReactNode;
  footer?: ReactNode;
  children?: ReactNode;
}

export function CompositionRoot({
  title,
  description,
  headingLevel = 2,
  shadow = "auto",
  theme,
  action,
  footer,
  children,
  className,
  "data-balsa": _dataBalsa,
  ...domProps
}: CompositionRootProps) {
  void _dataBalsa;

  return (
    <ApplicationCard
      {...domProps}
      title={title}
      description={description}
      headingLevel={headingLevel}
      shadow={shadow ?? "auto"}
      theme={theme}
      action={action}
      footer={footer}
      className={mergeClasses("min-w-0", className)}
    >
      {children}
    </ApplicationCard>
  );
}

import type { Shadow, ThemeInput } from "../ui/theme";

export interface CompositionSurfaceProps {
  headingLevel?: 2 | 3 | 4 | 5 | 6;
  shadow?: Shadow;
  theme?: ThemeInput;
}

export interface CompositionOption {
  label: string;
  value: string;
  description?: string;
}

export interface CompositionMetric {
  label: string;
  value: string;
  detail?: string;
}

export type CompositionPaletteColor = "primary" | "secondary" | "accent";
